# hudmeter: each rule of src/quest/combat/hudmeter.cpp (and its targets) removed once; src/quest/tests/hudmeter_test.cpp must fail on every one.
# runm <module> <name> <file under src/quest/combat> <sed expression>
runm hudmeter hm_scope_ignored      hudmeter.cpp 's/^  if (!scope::InCombat()) return original(node, data);$//'
runm hudmeter hm_scope_inverted     hudmeter.cpp 's/if (!scope::InCombat()) return original(node, data);/if (scope::InCombat()) return original(node, data);/'
runm hudmeter hm_enroll_skipped     hudmeter.cpp 's/if (!scope::Enroll()) return Refused/if (false) return Refused/'
runm hudmeter hm_item_ignored       hudmeter.cpp 's/At<std::uint64_t>(d, kDataItem) != kItem || //'
runm hudmeter hm_item_off           hudmeter.cpp 's/At<std::uint64_t>(d, kDataItem) != kItem/At<std::uint64_t>(d, kDataItem + 8) != kItem/'
runm hudmeter hm_sizeflag_ignored   hudmeter.cpp 's/ || At<std::int32_t>(d, kDataSizeOn) == 0//'
runm hudmeter hm_only_lobby_comp    hudmeter.cpp 's/if (At<std::uint64_t>(d, kDataComponent) != kLobbyComponent) LogOtherComp(At<std::uint64_t>(d, kDataComponent));/if (At<std::uint64_t>(d, kDataComponent) != kLobbyComponent) { (void)\&LogOtherComp; return original(node, data); }/'
runm hudmeter hm_no_size_restore    hudmeter.cpp 's/std::memcpy(size, d + kDataSize, sizeof kFull);.*$/(void)size;/'
runm hudmeter hm_no_full_write      hudmeter.cpp 's/^  std::memcpy(size, kFull, sizeof kFull);$/  (void)kFull;/'
runm hudmeter hm_full_swapped       hudmeter.cpp 's/kFull\[2\] = {kFullX, kFullY}/kFull[2] = {kFullY, kFullX}/'
runm hudmeter hm_half_zero          hudmeter.cpp 's/if (x != 0.0f || y != 0.0f) {/if (x != 0.0f \&\& y != 0.0f) {/'
runm hudmeter hm_unreadable_drops   hudmeter.cpp 's/g_unreadable.fetch_add(1, std::memory_order_relaxed);/g_unreadable.fetch_add(1, std::memory_order_relaxed); return 0;/'
runm hudmeter hm_result_dropped     hudmeter.cpp 's/^  return result;$/  return result + 1;/'
runm hudmeter hm_pass_repeats       hudmeter.cpp 's/^  g_passed.store(false, std::memory_order_relaxed);.*$//'
runm hudmeter hm_full_unthinned     hudmeter.cpp 's/if (n \& (n - 1)) return;.*$//'
runm hudmeter hm_fill_uncapped      hudmeter.cpp 's/>= kFillLines) return;/>= (kFillLines + 100000u)) return;/'
runm hudmeter hm_comp_named_often   hudmeter.cpp 's/if (!g_otherComp.compare_exchange_strong(none, comp, std::memory_order_relaxed)) return;/(void)none;/'
runm hudmeter hm_refusal_quiet      hudmeter.cpp 's/sentinel::LogFields(ok ? sentinel::LogLevel::kInfo : sentinel::LogLevel::kError, "combat_hudmeter_install"/sentinel::LogFields(sentinel::LogLevel::kInfo, "combat_hudmeter_install"/'
runm hudmeter hm_off_installs       hudmeter.cpp 's/^  if (!on) {$/  if (!on \&\& lookup == nullptr) {/'
runm hudmeter hm_wrong_slot         hudmeter_targets.h 's/kSlotVaddr = 0x36c6ce8ULL/kSlotVaddr = 0x36c6cf0ULL/'
runm hudmeter hm_wrong_fn           hudmeter_targets.h 's/kFnVaddr = 0x2726eacULL/kFnVaddr = 0x2726eb0ULL/'
runm hudmeter hm_wrong_item         hudmeter_targets.h 's/kItem = 0x9fd2e8cc0e46df3cULL/kItem = 0x9fd2e8cc0e46df3dULL/'
runm hudmeter hm_wrong_full         hudmeter_targets.h 's/kFullX = 86.0f, kFullY = 88.0f/kFullX = 86.0f, kFullY = 80.0f/'
runm hudmeter hm_original_unchecked hudmeter_targets.h 's/^  target.expectedOriginal = .*$/  (void)base;/'
